\label{1.1}
Let $H$ be a Krull monoid with finite class group $G$ where $|G| \ge 3$ and each class contains a prime divisor. Then the following statements are equivalent{\rm \,:}
\begin{enumerate}
\item[(a)] $\mathsf c (H) = \mathsf D (G)-1$.

\smallskip
\item[(b)] $\daleth (H) = \mathsf D (G)-1$.


\smallskip
\item[(c)] $G$ is isomorphic either to $C_2^{r-1} \oplus C_4$ for some $r \ge 2$ or  to $C_2 \oplus C_{2n}$ for some $n \ge 2$.

\end{enumerate}

\label{1.2}
Let $\mathcal O$ be a holomorphy ring in a global field $K$,  and $R$ a classical maximal $\mathcal O$-order in a central simple algebra $A$ over $K$ such that every stably free left $R$-ideal is free. Suppose that the  ray class group $G=\mathcal C_A ( \mathcal O)$ of $\mathcal O$ has at least three elements, let $\mathsf d$ denote a $($suitable$)$ distance on $R$, and $\mathsf c_{\mathsf d}(R)$ the $\mathsf d$-catenary degree of $R$. Then the following statements are equivalent{\rm \,:}
\begin{enumerate}
\item[(a)] $\mathsf c_{\mathsf d} (R) = \mathsf D (G)-1$.

\smallskip
\item[(b)] $\daleth (R) = \mathsf D (G)-1$.

\smallskip
\item[(c)] $G$ is isomorphic either to $C_2^{r-1} \oplus C_4$ for some $r \ge 2$ or  to $C_2 \oplus C_{2n}$ for some $n \ge 2$.

\end{enumerate}

\label{1.3}
Let $G$ be an abelian group.
\begin{enumerate}
\item If $\mathcal L (G) = \mathcal L ( C_2^{r-1} \oplus C_4 )$ for some $r \ge 2$, then $G \cong C_2^{r-1} \oplus C_4$.

\smallskip
\item If $\mathcal L (G) = \mathcal L ( C_2 \oplus C_{2n} )$ for some $n \ge 2$, then $G \cong C_2 \oplus C_{2n}$.
\end{enumerate}

\label{2.1}
Let $H$ be a Krull monoid, $\varphi \colon H \to F = \mathcal F (P)$ a divisor theory, $G = \mathcal C(\varphi)$ the class group, and suppose that each class contains a prime divisor. Let $\widetilde{\boldsymbol \beta} \colon \mathcal F (P) \to \mathcal F (G)$ denote the unique homomorphism satisfying $\widetilde{\boldsymbol \beta} (p) = [p]$ for each $p \in P$, and let $\boldsymbol \beta = \widetilde{\boldsymbol \beta} \circ \varphi \colon H \to \mathcal B (G)$.
\begin{enumerate}
\item For each $a \in H$, we have $\mathsf L_H (a) = \mathsf L_{\mathcal B (G)} ( \boldsymbol \beta (a))$. In particular, $\mathcal L (H) = \mathcal L (G)$, $\Delta (H)=\Delta (G)$, and $\daleth (H) = \daleth (G)$.

\smallskip
\item We have $|G|\le 2$ if and only if $\mathsf D (G)\le 2$ if and only if $|L|=1$ for all $L \in \mathcal L (G)$.

\smallskip
\item If $|G| \ge 3$, then $\mathsf c (H) = \mathsf c (G)$.
    \end{enumerate}

\label{3.1}
Let $G$ be a finite abelian group with $|G| \ge 3$, say $G = C_{n_1} \oplus \ldots \oplus C_{n_r}$ with $1 < n_1 \, | \, \ldots \, | \, n_r$.
\begin{enumerate}
\item $\mathsf c(G) \leq \max \Big\{ \Big\lfloor\frac{1}{2} \mathsf D(G)+1 \Big\rfloor,\, \daleth (G) \Big\}$.

\item $\daleth (G) \ge  \max\{n_r,\,1+\sum_{i=1}^{r}\lfloor\frac{n_i}{2}\rfloor\}$.
\end{enumerate}

\label{3.2}
Let $G$ be an abelian group with $|G| \ge 3$, and let $U,\,V\in \mathcal A(G)$ with $\max \mathsf L (UV) \ge 3$.
\begin{enumerate}
\item  Let $K \subset  G$ be a finite cyclic subgroup.  If $\sum_{h \in K} \mathsf v_h (UV) >  |K|$ and there exists a non-zero $g \in K$ such that $\mathsf v_{g}(U)>0$ and
       $\mathsf v_{-g}(V)>0$, then $\mathsf L (UV)\cap [3,|K|] \ne \emptyset$.

\smallskip
\item If $\mathsf L (UV)\cap [3, \operatorname{ord} (g)] = \emptyset$ for some  $g \in G$, then  $\mathsf v_g (U) + \mathsf v_{-g} (V) \le \operatorname{ord} (g)$.
\end{enumerate}

\label{3.4}
Let $G$ be a finite abelian group with $|G| \ge 3$ and $U \in \mathcal A (G)$ with $|U|=\mathsf D (G)$.
\begin{enumerate}
\item If $g_1,g_2, h\in \operatorname{supp}(U)$, then $g_1\neq 2g_2$, and if $\operatorname{ord}(h)=2$, then $g_1\neq 2g_2+h$.

\smallskip
\item Let $g \in G$ with $\mathsf v_g(U)=k \ge1$ and $\operatorname{ord}(g)>2$ and suppose that $|\operatorname{supp}(U)|\ge2$. Then there exists some $W \in \mathcal A (G)$ such that $W\, | \, (-g)^k g^{-k}U$ and  $|W| \in [3,  \mathsf D(G)-1]$.
\end{enumerate}

\label{3.5}
Let $G$ be a finite abelian group with $\mathsf D (G) \ge 5$. Then the following statements are equivalent{\rm \,:}
\begin{enumerate}
\item[(a)] $G$ is isomorphic  to $C_2 \oplus C_{2n}$ with $n \ge 2$.

\smallskip
\item[(b)] There exist  $U, V \in \mathcal A (G)$ with $\mathsf L (UV)= \{2, \mathsf D (G)-1, \mathsf D (G)\}$.
\end{enumerate}

\label{3.7}
Let $G$ be a finite abelian group with $\mathsf D(G) \ge 5$.
Then the following statements are equivalent{\rm \,:}
\begin{enumerate}
\item[(a)] $G$ is either an elementary $2$-group,  or a cyclic group, or isomorphic  to $C_2 \oplus C_{2n}$ with $n \ge 2$.

\smallskip
\item[(b)] There exist  $U, V \in \mathcal A (G)$ with $\mathsf L (UV)= \{2, \mathsf D (G)-1\}$ and $|U|-1=|V|=\mathsf D (G)-1$.
\end{enumerate}

\label{3.8}
Let $G$ be a finite abelian group with $\mathsf D (G) \ge  5$.
Then the following statements are equivalent{\rm \,:}
\begin{enumerate}
\item[(a)] $G$ is either an elementary $2$-group, or  isomorphic  to $C_2^{r-1}\oplus C_4$ for some  $r \ge 2$, or isomorphic to $C_2 \oplus C_{2n}$ for some $n \ge 2$.

\smallskip
\item[(b)] There exist  $U, V \in \mathcal A (G)$ with $\mathsf L (UV)= \{2, \mathsf D (G)-1\}$ and $|U|=|V|=\mathsf D (G)-1$.
\end{enumerate}
